/* Editorial selections reference, but never modify, the full catalogue. */
(() => {
  const q=s=>document.querySelector(s);
  const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const data=()=>window.STEM_DATA.top_picks;
  const selection={category:'',kid:'',horizon:'now',query:''};
  const fitNames={candidate:'возрастной / школьный кандидат',confirm:'допуск уточнить',future:'позже',no:'возраст закрыт'};
  const tierNames={main:'Основной выбор',alternative:'Альтернатива под задачу'};
  function matching(p){return (!selection.category||p.category===selection.category)&&(!selection.horizon||p.horizon===selection.horizon)&&(!selection.kid||(selection.kid==='both'?p.fit.mat==='candidate'&&p.fit.osc==='candidate':p.fit[selection.kid]!=='no'))&&(!selection.query||JSON.stringify(p).toLocaleLowerCase('ru').includes(selection.query.toLocaleLowerCase('ru')))}
  function card(p){
    const school=p.category==='school',league=p.category==='league';
    const actions=p.target_ids.map(id=>school?`<button class="button secondary" data-school-open="${safe(id)}">Школьное досье ↗</button>`:league?`<button class="button secondary" data-best-league="${safe(id)}">Правила и маршрут ↗</button>`:`<button class="button secondary" data-open="${safe(id)}">${p.target_ids.length>1?safe(window.STEM_DATA.events.find(e=>e.id===id)?.title.replace(/^.*? · /,'')):'Полное досье'} ↗</button>`).join('');
    return `<article class="best-card ${safe(p.category)} ${safe(p.tier)}" id="best-${safe(p.id)}" data-pick-id="${safe(p.id)}" tabindex="-1"><div class="best-card-heading"><span>${safe(data().categories[p.category])} · ${safe(p.place)}</span><span class="best-star" aria-hidden="true">✦</span></div><div class="best-card-body"><div class="best-tags"><span>${p.horizon==='future'?'Будущий маршрут':safe(tierNames[p.tier])}</span><span>${p.horizon==='future'?'Возраст позже':'Ступень для рассмотрения сейчас'}</span></div><h3>${safe(p.title)}</h3><p class="best-promise">${safe(p.label)}</p><p>${safe(p.why)}</p><div class="best-fit">${['mat','osc'].map(k=>`<span class="${safe(p.fit[k])}">${k==='mat'?'Матвей':'Оскар'} · ${safe(fitNames[p.fit[k]])}</span>`).join('')}</div><div class="best-facts"><strong>Что подтверждено</strong><p>${safe(p.facts)}</p></div><div class="best-gate"><strong>Что решить до выбора</strong><p>${safe(p.gate)}</p></div><details class="best-details"><summary>Следующий шаг и первичные источники</summary><p>${safe(p.next_action)}</p>${p.sources.map(s=>`<a href="${safe(s.url)}" target="_blank" rel="noopener">${safe(s.title)} ↗</a>`).join('')}<small>Сверено 01.10.2026 · качество занятия лично ещё не проверено</small></details><div class="best-card-actions">${actions}</div></div></article>`;
  }
  function render(){
    const d=data(),root=q('#best-content');if(!d||!root)return;
    if(!root.dataset.ready){root.innerHTML=`<div class="best-hero"><div><p class="best-eyebrow">✦ СЕМЕЙНЫЙ ВЫБОР · 6 И 9 ЛЕТ</p><h3>Сильная команда.<br><em>Собственный проект.</em></h3><p>${safe(d.recommendation)}</p><a class="text-button" href="downloads/STEM_top_picks.md" download>Скачать подборку с источниками ↓</a></div><div class="best-orbit" aria-hidden="true"><span class="orbit-ring one"></span><span class="orbit-ring two"></span><span class="orbit-ring three"></span><span class="orbit-core">✦</span><span class="orbit-point p1">Школа</span><span class="orbit-point p2">Команда</span><span class="orbit-point p3">Проект</span></div></div><p class="best-basis">${safe(d.basis)}</p><div class="best-category-tabs" role="group" aria-label="Раздел подборки"><button data-best-category="">Все ${d.picks.length}</button>${Object.entries(d.categories).map(([k,v])=>`<button data-best-category="${k}">${safe(v)} <small>${d.picks.filter(p=>p.category===k).length}</small></button>`).join('')}</div><div class="best-controls"><label>Горизонт<select data-best-filter="horizon"><option value="now">Рассматривать сейчас · набор отдельно</option><option value="future">Будущие возрастные ступени</option><option value="">Сейчас и будущее</option></select></label><label>Для кого<select data-best-filter="kid"><option value="">Оба маршрута</option><option value="mat">Матвей · кандидаты / позже</option><option value="osc">Оскар · кандидаты / позже</option><option value="both">Обоим · возрастные / школьные кандидаты</option></select></label><label>Найти в подборке<input data-best-filter="query" type="search" placeholder="Тайвань, пансион, ИИ…"></label><button class="text-button" data-best-reset>Сбросить</button></div><p id="best-count" class="best-count" aria-live="polite"></p><div id="best-cards" class="best-grid"></div><details class="best-method"><summary>Почему эти варианты и где границы выбора</summary><ul>${d.methodology.map(t=>`<li>${safe(t)}</li>`).join('')}</ul><p>Приоритет не равен принятой заявке, открытой смене или гарантии медали. Бюджет сравнивается в полных досье. Дневная первичная ступень и пансион старших оцениваются отдельно.</p><a href="downloads/STEM_top_picks.json" download>Подборка · JSON ↓</a></details>`;root.dataset.ready='true'}
    root.querySelectorAll('[data-best-filter]').forEach(el=>{if(el.value!==selection[el.dataset.bestFilter])el.value=selection[el.dataset.bestFilter]});
    root.querySelectorAll('[data-best-category]').forEach(el=>{const on=el.dataset.bestCategory===selection.category;el.classList.toggle('active',on);el.setAttribute('aria-pressed',String(on))});
    const a=d.picks.filter(matching);q('#best-count').textContent=`${a.length} из ${d.picks.length} рекомендаций · «сейчас» описывает ступень, а не подтверждённое место. Будущая дата и набор указаны в досье.`;
    q('#best-cards').innerHTML=a.length?a.map(card).join(''):'<div class="best-empty"><h3>В этой подборке совпадений нет</h3><p>Попробуйте другой горизонт или ребёнка. Полный каталог шире редакционной подборки.</p><button class="button secondary" data-best-reset>Показать все рекомендации</button></div>';
  }
  window.renderBest=render;
  window.bestPickFor=(category,id)=>data()?.picks.find(p=>p.category===category&&p.target_ids.includes(id));
  window.bestEventPick=id=>data()?.picks.find(p=>(['camp','expo'].includes(p.category)&&p.target_ids.includes(id))||(p.event_ids||[]).includes(id));
  window.bestBadge=(category,id)=>{const p=category==='event'?window.bestEventPick(id):window.bestPickFor(category,id);return p?`<button class="best-badge" data-best-pick="${safe(p.id)}" title="${safe(p.label)}">✦ ${p.horizon==='future'?'Наш выбор · позже':'Наш выбор'} ↗</button>`:''};
  document.addEventListener('click',e=>{
    const b=e.target.closest('button');if(!b)return;
    if(b.hasAttribute('data-best-category')){selection.category=b.dataset.bestCategory;render()}
    if(b.hasAttribute('data-best-reset')){Object.assign(selection,{category:'',kid:'',horizon:'',query:''});render()}
    if(b.dataset.bestPick){Object.assign(selection,{category:'',kid:'',horizon:'',query:''});setView('best');const el=q('#best-'+b.dataset.bestPick);el?.scrollIntoView({behavior:'smooth',block:'start'});el?.focus({preventScroll:true})}
    if(b.dataset.bestLeague){setView('leagues');Object.assign(leagueState,{tab:'guide',query:'',group:'',age:'',best:false});leagueState.opened.add(b.dataset.bestLeague);renderLeagueGuide();const el=q('#league-'+b.dataset.bestLeague);el?.scrollIntoView({behavior:'smooth',block:'start'});el?.querySelector('summary')?.focus({preventScroll:true})}
  });
  document.addEventListener('change',e=>{const k=e.target.dataset.bestFilter;if(k&&k!=='query'){selection[k]=e.target.value;render()}});
  document.addEventListener('input',e=>{if(e.target.dataset.bestFilter==='query'){selection.query=e.target.value;render()}});
})();
